import { describe, expect, it } from "vitest";

import { Failure, Success } from "@/core/Result.ts";

describe("Result", () => {

  it("`Success.fold` runs only the success branch", () => {
    const result = new Success(21).fold(() => "failed", (n: number) => `got ${n * 2}`);
    expect(result).toBe("got 42");
  });

  it("`Failure.fold` runs only the failure branch", () => {
    const result = new Failure(new Error("boom")).fold((e: Error) => `failed: ${e.message}`, () => "succeeded");
    expect(result).toBe("failed: boom");
  });

  it("exposes `isOK` for narrowing", () => {
    expect(new Success("x").isOK).toBe(true);
    expect(new Failure(new Error("x")).isOK).toBe(false);
  });

});
